  if (response.p != null) {
    const stripped = await stripIsPartialByte(response.p)
    const buffer = await bufferPrefetchResponseBody(stripped.stream)
    prefetchResponse = await decodeBufferedResponse<NavigationFlightResponse>(
      buffer,
      undefined
