      shellResponse = null
    } else if (stageByteLengths.length === 0) {
      // The shell is the full response.
      shellResponse = prefetchResponse
    } else {
      shellResponse = await decodeResponsePrefix<NavigationFlightResponse>(
        [buffer],
        stageByteLengths[AppStage.Shell],
        undefined
