    prefetchResponse = response
    isPartial = false
    staleAt = await resolveStaleAt(now, response.s)
    if (responseChunks !== null) {
      shellResponse = await resolveStageResponse(
        responseChunks,
        response,
        AppStage.Shell,
        undefined
